// Graphile Worker schema bootstrap (step 3 of the migration order).
//
// The job-queue schema (`graphile_worker`) is owned by Graphile Worker, not by
// Drizzle, so it is migrated separately from the app schema. We do NOT let the
// worker self-install on boot — installation is an explicit, ordered step:
//
//   1. Better Auth schema (committed in the Drizzle schema)         } `npm run db:migrate`
//   2. Liedmotif app migrations generated by Drizzle                 }
//   3. Graphile Worker schema  <-- THIS SCRIPT (`npm run db:migrate:worker`)
//
// `runMigrations` is the library equivalent of the `graphile-worker
// --schema-only` CLI: it installs or updates the schema and exits. It owns and
// releases its own pool when given a connection string.

import { runMigrations } from 'graphile-worker';
import { assertNotTestDatabase } from '@liedmotif/db';
import { createLogger, requireEnv } from '@liedmotif/shared';

const log = createLogger({ name: 'worker-migrate' });

async function main(): Promise<void> {
  // `requireEnv` throws a clear error if unset; the connection string itself is
  // never logged (it carries inline credentials).
  const connectionString = requireEnv('DATABASE_URL');
  assertNotTestDatabase(connectionString);
  log.info('installing/updating graphile_worker schema');
  await runMigrations({ connectionString });
  log.info('graphile_worker schema is up to date');
}

main()
  .then(() => process.exit(0))
  .catch((err) => {
    log.error('graphile_worker migration failed', { err });
    process.exit(1);
  });
